const h="https://api.tradres.com.tr/public/v1/catalog/providers/localsqlite/nodes";let l=null;const u=new Map,f=new Map;function p(r){return r?r.trim().split(/\s+/).map(s=>{if(!s)return"";if(/^\d+/.test(s))return s;const a=s.charAt(0),e=s.slice(1),o=a.replace(/i/g,"İ").replace(/ı/g,"I").toLocaleUpperCase("tr-TR"),t=e.replace(/İ/g,"i").replace(/I/g,"ı").toLocaleLowerCase("tr-TR");return o+t}).join(" "):""}function c(r){return r?String(r).replace(/İ/g,"i").replace(/I/g,"ı").toLowerCase().replace(/ç/g,"c").replace(/ğ/g,"g").replace(/ı/g,"i").replace(/ö/g,"o").replace(/ş/g,"s").replace(/ü/g,"u").replace(/\s+/g,"").replace(/mahallesi$/i,"").replace(/mah\.?$/i,"").trim():""}async function d(){if(l&&l.length>0)return l;try{const r=sessionStorage.getItem("muavinn_tradres_provinces");if(r){const n=JSON.parse(r);if(Array.isArray(n)&&n.length>=80)return l=n,n}}catch{}try{const r=await fetch(`${h}?level=province&take=200`);if(!r.ok)throw new Error(`TrAdres API responded with status ${r.status}`);const n=await r.json();if(Array.isArray(n)&&n.length>0){const s=n.map(a=>{const e=a.id,o=e<10?`0${e}`:String(e),t=p(a.name);return{id:e,code:o,name:t,rawName:a.name}});s.sort((a,e)=>a.id-e.id),l=s;try{sessionStorage.setItem("muavinn_tradres_provinces",JSON.stringify(s))}catch{}return s}}catch(r){console.warn("Could not fetch provinces from TrAdres API, will use fallback:",r)}return[]}async function g(r){let n=null;if(typeof r=="number")n=r;else{const a=await d(),e=c(r),o=a.find(t=>t.code===r||t.id===Number(r)||c(t.name)===e||c(t.rawName)===e);if(o)n=o.id;else{const t=parseInt(r,10);!isNaN(t)&&t>=1&&t<=81&&(n=t)}}if(!n)return[];if(u.has(n))return u.get(n);const s=`muavinn_tradres_districts_${n}`;try{const a=sessionStorage.getItem(s);if(a){const e=JSON.parse(a);if(Array.isArray(e)&&e.length>0)return u.set(n,e),e}}catch{}try{const a=await fetch(`${h}?level=town&parentId=${n}&take=300`);if(!a.ok)throw new Error(`TrAdres API town status ${a.status}`);const e=await a.json();if(Array.isArray(e)&&e.length>0){const o=e.map(t=>({id:t.id,name:p(t.name),rawName:t.name,provinceId:n}));o.sort((t,i)=>t.name.localeCompare(i.name,"tr-TR")),u.set(n,o);try{sessionStorage.setItem(s,JSON.stringify(o))}catch{}return o}}catch(a){console.warn(`Could not fetch districts for province ${n} from TrAdres:`,a)}return[]}async function y(r,n){let s=null;if(typeof r=="number")s=r;else if(n){const e=await g(n),o=c(r),t=e.find(i=>i.id===Number(r)||c(i.name)===o||c(i.rawName)===o);t&&(s=t.id)}if(!s){const e=parseInt(String(r),10);!isNaN(e)&&e>100&&(s=e)}if(!s)return[];if(f.has(s))return f.get(s);const a=`muavinn_tradres_quarters_${s}`;try{const e=sessionStorage.getItem(a);if(e){const o=JSON.parse(e);if(Array.isArray(o)&&o.length>0)return f.set(s,o),o}}catch{}try{const e=await fetch(`${h}?level=quarter&parentId=${s}&take=500`);if(!e.ok)throw new Error(`TrAdres API quarter status ${e.status}`);const o=await e.json();if(Array.isArray(o)&&o.length>0){const t=o.map(i=>({id:i.id,name:p(i.name),rawName:i.name,townId:s}));t.sort((i,m)=>i.name.localeCompare(m.name,"tr-TR")),f.set(s,t);try{sessionStorage.setItem(a,JSON.stringify(t))}catch{}return t}}catch(e){console.warn(`Could not fetch neighborhoods for town ${s} from TrAdres:`,e)}return[]}export{g as a,y as b,d as f,c as n};
